import { createHash, timingSafeEqual } from "node:crypto";
import { BlockList, isIP } from "node:net";
import type { RequestHandler, Response } from "express";

/**
 * Peer authentication.
 *
 * A peer has no user accounts. Its data routes are protected by one shared bearer token
 * generated by the main during onboarding, plus an optional address allowlist. The token is
 * compared through fixed-length digests so the comparison is constant-time and does not leak
 * the secret's length.
 */

function buildAllowList(entries: string[]): BlockList {
  const list = new BlockList();

  for (const entry of entries) {
    const slash = entry.indexOf("/");
    let address = slash === -1 ? entry : entry.slice(0, slash);
    const prefixRaw = slash === -1 ? null : entry.slice(slash + 1);

    const mapped = /^::ffff:(\d{1,3}(?:\.\d{1,3}){3})$/i.exec(address);
    if (mapped?.[1] !== undefined && isIP(mapped[1]) === 4) {
      address = mapped[1];
    }

    const familyCode = isIP(address);
    if (familyCode === 0) {
      throw new Error(`invalid peer allowlist entry "${entry}": not an IP address`);
    }
    const family = familyCode === 4 ? "ipv4" : "ipv6";

    if (prefixRaw === null) {
      list.addAddress(address, family);
      continue;
    }

    if (!/^\d{1,3}$/.test(prefixRaw)) {
      throw new Error(`invalid peer allowlist entry "${entry}": prefix is not a number`);
    }
    const prefix = Number.parseInt(prefixRaw, 10);
    if (prefix > (familyCode === 4 ? 32 : 128)) {
      throw new Error(`invalid peer allowlist entry "${entry}": prefix is out of range`);
    }

    list.addSubnet(address, prefix, family);
  }

  return list;
}

/** Strip an IPv4-mapped prefix and an IPv6 zone so the matcher sees one canonical address. */
function remoteAddressOf(raw: string | undefined): string | null {
  if (raw === undefined) return null;
  const withoutZone = raw.split("%")[0] ?? raw;
  const mapped = /^::ffff:(\d{1,3}(?:\.\d{1,3}){3})$/i.exec(withoutZone);
  if (mapped?.[1] !== undefined && isIP(mapped[1]) === 4) return mapped[1];
  return isIP(withoutZone) === 0 ? null : withoutZone;
}

function deny(response: Response, status: 401 | 403, code: string, message: string): void {
  if (status === 401) {
    response.set("WWW-Authenticate", 'Bearer realm="rackdeck"');
  }
  response.status(status).json({ error: { code, message } });
}

function tokenMatches(expected: string, supplied: string): boolean {
  const expectedDigest = createHash("sha256").update(expected, "utf8").digest();
  const suppliedDigest = createHash("sha256").update(supplied, "utf8").digest();
  return timingSafeEqual(expectedDigest, suppliedDigest);
}

export function createPeerAuth(options: {
  token: string;
  allowedIps: string[] | null;
}): RequestHandler {
  const allowList = options.allowedIps === null ? null : buildAllowList(options.allowedIps);

  return (request, response, next) => {
    if (allowList !== null) {
      const address = remoteAddressOf(request.socket.remoteAddress);
      const family = address === null ? 0 : isIP(address);
      if (
        address === null ||
        family === 0 ||
        !allowList.check(address, family === 4 ? "ipv4" : "ipv6")
      ) {
        deny(response, 403, "forbidden", "This address is not allowed to read this peer.");
        return;
      }
    }

    const header = request.get("authorization")?.trim();
    if (header === undefined || header.length === 0) {
      deny(response, 401, "unauthorized", "A valid peer token is required.");
      return;
    }

    const match = /^Bearer\s+(\S+)$/i.exec(header);
    if (match?.[1] === undefined) {
      deny(response, 401, "unauthorized", "A valid peer token is required.");
      return;
    }

    if (!tokenMatches(options.token, match[1])) {
      deny(response, 401, "unauthorized", "A valid peer token is required.");
      return;
    }

    next();
  };
}
